public class InnerQueueWeightedBalancedSchedulingConfigurationFactory(Action<Humidifier.Deadline.QueueTypes.WeightedBalancedSchedulingConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Deadline.QueueTypes.WeightedBalancedSchedulingConfiguration>
{

    internal InnerQueueSchedulingMaxPriorityOverrideFactory MaxPriorityOverrideFactory { get; set; }

    internal InnerQueueSchedulingMinPriorityOverrideFactory MinPriorityOverrideFactory { get; set; }

    protected override Humidifier.Deadline.QueueTypes.WeightedBalancedSchedulingConfiguration Create()
    {
        var weightedBalancedSchedulingConfigurationResult = CreateWeightedBalancedSchedulingConfiguration();
        factoryAction?.Invoke(weightedBalancedSchedulingConfigurationResult);

        return weightedBalancedSchedulingConfigurationResult;
    }

    private Humidifier.Deadline.QueueTypes.WeightedBalancedSchedulingConfiguration CreateWeightedBalancedSchedulingConfiguration()
    {
        var weightedBalancedSchedulingConfigurationResult = new Humidifier.Deadline.QueueTypes.WeightedBalancedSchedulingConfiguration();

        return weightedBalancedSchedulingConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Deadline.QueueTypes.WeightedBalancedSchedulingConfiguration result)
    {
        base.CreateChildren(result);

        result.MaxPriorityOverride ??= MaxPriorityOverrideFactory?.Build();
        result.MinPriorityOverride ??= MinPriorityOverrideFactory?.Build();
    }

} // End Of Class

